// Normalize the worker_soar container step into a Kubernetes API request.
// cordon_node / quarantine_container (deny-all NetworkPolicy) / kill_pod / uncordon_node.
const body = $input.first().json.body || $input.first().json;
const action = body.action || 'quarantine_container';
return [{ json: {
  incident_id: body.incident_id || 'UNKNOWN',
  target: body.target || '',
  action: action,
  api_url: $env.K8S_CONTAINMENT_GATEWAY_URL,
  api_body: JSON.stringify({ incident_id: body.incident_id, target: body.target, action, namespace: body.namespace || 'default' }),
} }];

// Inbound auth (threat-model F-2): the request must carry a valid HMAC-SHA256 of
// the raw body in X-Nexus-Signature, keyed by NEXUS_HMAC_SECRET. Reject otherwise,
// so a deepnet-reachable attacker cannot drive containment by POSTing to the webhook.
const crypto = require('crypto');
const item = $input.first().json;
const raw = (item.rawBody !== undefined && item.rawBody !== null)
  ? (typeof item.rawBody === 'string' ? item.rawBody : JSON.stringify(item.rawBody))
  : JSON.stringify(item.body || {});
const headers = item.headers || {};
const provided = headers['x-nexus-signature'] || headers['X-Nexus-Signature'] || '';
const expected = crypto.createHmac('sha256', $env.NEXUS_HMAC_SECRET || '').update(raw).digest('hex');
if (!provided || provided.length !== expected.length || provided !== expected) {
  throw new Error('invalid X-Nexus-Signature -- refusing containment');
}
return [{ json: item.body || item }];
